import numpy as np
# invalid input: a non-positive radius is not a sphere and must raise ValueError
def _catches_value_error(fn):
    try:
        fn()
    except ValueError:
        return np.array([1.0])
    return np.array([0.0])
assert np.allclose(_catches_value_error(lambda: box_spectrum(-1.0, 3, 2)), target)

